self.EXB_INLINE = {"worker":"self.EXB_WASM_B64=\"\";\n// Generated by tools/build-data.mjs — do not edit.\nself.EXB_DATA = {\"lib\":{\"pratt.exb\":\"// pratt.exb — a Pratt (top-down operator precedence) parser toolkit.\\n//\\n//   let pratt = require(\\\"pratt\\\")\\n//   let spec = {\\n//     prefix: { NUM: fn(p, t) { return {type: \\\"num\\\", value: num(t.text)} } },\\n//     infix:  { PLUS: pratt.binary(10, false) }\\n//   }\\n//   let ast = pratt.parser(lexer.tokenize(src), spec).parse(0)\\n//\\n// prefix rules  : fn(p, token)        -> node\\n// infix rules   : {prec: n, fn: fn(p, left, token) -> node}\\n// Tokens are looked up by their `type`; name operator rules after the operator\\n// itself (lexer rule [\\\"+\\\", \\\"\\\\\\\\+\\\"]) and the spec tables read naturally.\\n// The parser object `p` offers: peek() next() check(type) match(type)\\n// expect(type, msg) parse(prec) at_end() and fail(msg).\\n\\nfn parser(tokens, spec) {\\n  let st = {pos: 0}\\n  let p = {}\\n\\n  p.peek = fn() { return tokens[st.pos] }\\n  p.at_end = fn() { return tokens[st.pos].type == \\\"EOF\\\" }\\n  p.next = fn() {\\n    let t = tokens[st.pos]\\n    if t.type != \\\"EOF\\\" { st.pos += 1 }\\n    return t\\n  }\\n  p.check = fn(type) { return tokens[st.pos].type == type }\\n  p.match = fn(type) {\\n    if tokens[st.pos].type == type {\\n      st.pos += 1\\n      return true\\n    }\\n    return false\\n  }\\n  p.fail = fn(msg) {\\n    let t = tokens[st.pos]\\n    let near = t.text\\n    if t.type == \\\"EOF\\\" { near = \\\"end of input\\\" }\\n    error(format(\\\"Parse error at %d:%d: %s (near '%s')\\\", t.line, t.col, msg, near))\\n  }\\n  p.expect = fn(type, msg) {\\n    if tokens[st.pos].type == type {\\n      return p.next()\\n    }\\n    if msg == nil { msg = \\\"expected \\\" + type }\\n    p.fail(msg)\\n  }\\n  p.parse = fn(prec) {\\n    let t = p.next()\\n    let pre = spec.prefix[t.type]\\n    if pre == nil {\\n      st.pos -= 1\\n      p.fail(\\\"unexpected token \\\" + t.type)\\n    }\\n    let left = pre(p, t)\\n    while true {\\n      let nt = tokens[st.pos]\\n      let rule = spec.infix[nt.type]\\n      if rule == nil { break }\\n      if rule.prec <= prec { break }\\n      p.next()\\n      left = rule.fn(p, left, nt)\\n    }\\n    return left\\n  }\\n  return p\\n}\\n\\n// Ready-made rule builders ---------------------------------------------------\\n\\nfn binary(prec, right_assoc) {\\n  return {prec: prec, fn: fn(p, left, t) {\\n    let rbp = prec\\n    if right_assoc { rbp = prec - 1 }\\n    return {type: \\\"binary\\\", op: t.text, left: left, right: p.parse(rbp)}\\n  }}\\n}\\n\\nfn postfix(prec) {\\n  return {prec: prec, fn: fn(p, left, t) {\\n    return {type: \\\"postfix\\\", op: t.text, operand: left}\\n  }}\\n}\\n\\nfn unary(prec) {\\n  return fn(p, t) { return {type: \\\"unary\\\", op: t.text, operand: p.parse(prec)} }\\n}\\n\\n// Repeatedly parse items separated by `sep` until `close` (consumed).\\nfn separated(p, sep, close) {\\n  let items = []\\n  if p.match(close) { return items }\\n  while true {\\n    items.push(p.parse(0))\\n    if p.match(sep) { continue }\\n    p.expect(close, nil)\\n    break\\n  }\\n  return items\\n}\\n\\nreturn {parser: parser, binary: binary, postfix: postfix, unary: unary, separated: separated}\\n\",\"pretty.exb\":\"// pretty.exb — render any EXBIN value as an indented tree (handy for ASTs).\\nfn tree(v, indent) {\\n  if indent == nil { indent = 0 }\\n  let pad = \\\"  \\\".repeat(indent)\\n  let t = type(v)\\n  if t == \\\"map\\\" {\\n    if v.len == 0 { return \\\"{}\\\" }\\n    let out = \\\"{\\\\n\\\"\\n    for k in v.keys() {\\n      out += pad + \\\"  \\\" + str(k) + \\\": \\\" + tree(v[k], indent + 1) + \\\"\\\\n\\\"\\n    }\\n    return out + pad + \\\"}\\\"\\n  }\\n  if t == \\\"list\\\" {\\n    if v.len == 0 { return \\\"[]\\\" }\\n    let out = \\\"[\\\\n\\\"\\n    for x in v { out += pad + \\\"  \\\" + tree(x, indent + 1) + \\\"\\\\n\\\" }\\n    return out + pad + \\\"]\\\"\\n  }\\n  return repr(v)\\n}\\n\\n// One-line s-expression form: {type:\\\"binary\\\", ...} -> (binary + a b)\\nfn sexpr(v) {\\n  let t = type(v)\\n  if t == \\\"map\\\" {\\n    let parts = []\\n    for k in v.keys() {\\n      if k == \\\"type\\\" { continue }\\n      parts.push(sexpr(v[k]))\\n    }\\n    let head = v.type\\n    if head == nil { head = \\\"map\\\" }\\n    let out = \\\"(\\\" + str(head)\\n    if parts.len > 0 { out += \\\" \\\" + parts.join(\\\" \\\") }\\n    return out + \\\")\\\"\\n  }\\n  if t == \\\"list\\\" { return \\\"[\\\" + v.map(sexpr).join(\\\" \\\") + \\\"]\\\" }\\n  return str(v)\\n}\\n\\nreturn {tree: tree, sexpr: sexpr}\\n\"},\"examples\":[{\"name\":\"hello.exb\",\"title\":\"مرحباً — جولة سريعة\",\"code\":\"// EXBIN in thirty seconds.\\nlet name = \\\"EXBIN\\\"\\nprint(\\\"Hello from\\\", name, EXBIN_VERSION)\\n\\nfn greet(who) { return \\\"مرحبا يا \\\" + who }\\nprint(greet(\\\"عالم\\\"))\\n\\nlet langs = [{n: \\\"Lua\\\", y: 1993}, {n: \\\"EXBIN\\\", y: 2026}, {n: \\\"Python\\\", y: 1991}]\\nlet by_year = langs.sort(fn(a, b) { return a.y - b.y })\\nfor l in by_year { print(format(\\\"%-8s %d\\\", l.n, l.y)) }\\nprint(\\\"sum of squares:\\\", list(range(1, 6)).map(fn(x) { return x * x }).sum())\\n\"},{\"name\":\"calc.exb\",\"title\":\"آلة حاسبة (Lexer + Pratt)\",\"code\":\"// calc.exb — a complete little language (lexer + Pratt parser + evaluator)\\n// in about 80 lines, built with EXBIN's own toolkit. Variables, functions,\\n// assignment, Arabic identifiers.\\nlet pratt = require(\\\"pratt\\\")\\n\\nlet lx = lexer([\\n  [\\\"_\\\", \\\"[ \\\\\\\\t]+\\\"],\\n  [\\\"NUM\\\", \\\"[0-9]+(\\\\\\\\.[0-9]+)?\\\"],\\n  [\\\"IDENT\\\", \\\"[A-Za-z_\\\\\\\\x80-\\\\\\\\xff][A-Za-z0-9_\\\\\\\\x80-\\\\\\\\xff]*\\\"],\\n  [\\\"**\\\", \\\"\\\\\\\\*\\\\\\\\*\\\"], [\\\"+\\\", \\\"\\\\\\\\+\\\"], [\\\"-\\\", \\\"-\\\"], [\\\"*\\\", \\\"\\\\\\\\*\\\"], [\\\"/\\\", \\\"/\\\"], [\\\"%\\\", \\\"%\\\"],\\n  [\\\"(\\\", \\\"\\\\\\\\(\\\"], [\\\")\\\", \\\"\\\\\\\\)\\\"], [\\\",\\\", \\\",\\\"], [\\\"=\\\", \\\"=\\\"]\\n])\\n\\nlet spec = {prefix: {}, infix: {}}\\nspec.prefix[\\\"NUM\\\"] = fn(p, t) { return {type: \\\"num\\\", value: num(t.text)} }\\nspec.prefix[\\\"IDENT\\\"] = fn(p, t) {\\n  if p.match(\\\"(\\\") {\\n    return {type: \\\"call\\\", name: t.text, args: pratt.separated(p, \\\",\\\", \\\")\\\")}\\n  }\\n  return {type: \\\"var\\\", name: t.text}\\n}\\nspec.prefix[\\\"(\\\"] = fn(p, t) {\\n  let e = p.parse(0)\\n  p.expect(\\\")\\\", \\\"expected ')'\\\")\\n  return e\\n}\\nspec.prefix[\\\"-\\\"] = pratt.unary(30)\\nspec.infix[\\\"=\\\"] = {prec: 1, fn: fn(p, left, t) {\\n  if left.type != \\\"var\\\" { p.fail(\\\"cannot assign to this\\\") }\\n  return {type: \\\"assign\\\", name: left.name, value: p.parse(0)}\\n}}\\nspec.infix[\\\"+\\\"] = pratt.binary(10, false)\\nspec.infix[\\\"-\\\"] = pratt.binary(10, false)\\nspec.infix[\\\"*\\\"] = pratt.binary(20, false)\\nspec.infix[\\\"/\\\"] = pratt.binary(20, false)\\nspec.infix[\\\"%\\\"] = pratt.binary(20, false)\\nspec.infix[\\\"**\\\"] = pratt.binary(40, true)\\n\\nlet builtins = {sqrt: sqrt, max: max, min: min, abs: abs, floor: floor, sin: sin, cos: cos}\\n\\nfn evaluate(n, env) {\\n  let t = n.type\\n  if t == \\\"num\\\" { return n.value }\\n  if t == \\\"var\\\" {\\n    if not env.has(n.name) { error(\\\"undefined variable '\\\" + n.name + \\\"'\\\") }\\n    return env[n.name]\\n  }\\n  if t == \\\"assign\\\" {\\n    let v = evaluate(n.value, env)\\n    env[n.name] = v\\n    return v\\n  }\\n  if t == \\\"neg\\\" or t == \\\"unary\\\" { return -evaluate(n.operand, env) }\\n  if t == \\\"call\\\" {\\n    let f = builtins[n.name]\\n    if f == nil { error(\\\"unknown function '\\\" + n.name + \\\"'\\\") }\\n    return apply(f, n.args.map(fn(a) { return evaluate(a, env) }))\\n  }\\n  let a = evaluate(n.left, env)\\n  let b = evaluate(n.right, env)\\n  if n.op == \\\"+\\\" { return a + b }\\n  if n.op == \\\"-\\\" { return a - b }\\n  if n.op == \\\"*\\\" { return a * b }\\n  if n.op == \\\"/\\\" {\\n    if b == 0 { error(\\\"division by zero\\\") }\\n    return a / b\\n  }\\n  if n.op == \\\"%\\\" { return a % b }\\n  return a ** b\\n}\\n\\nfn calc(src, env) {\\n  let p = pratt.parser(lx.tokenize(src), spec)\\n  let ast = p.parse(0)\\n  if not p.at_end() { p.fail(\\\"unexpected input\\\") }\\n  return evaluate(ast, env)\\n}\\n\\nlet env = {}\\nlet demo = [\\\"1 + 2 * 3\\\", \\\"x = 10\\\", \\\"y = x ** 2 / 4\\\", \\\"sqrt(y) + max(1, 2, 3)\\\",\\n            \\\"(1 + 2) * -3\\\", \\\"2 ** 3 ** 2\\\", \\\"عدد = 7\\\", \\\"عدد * 6\\\", \\\"1 / 0\\\", \\\"2 +\\\", \\\"foo(1)\\\"]\\nlet lines = demo\\nif args.len > 1 { lines = args.slice(1) }   // exbin calc.exb \\\"1+2\\\" \\\"x = 3\\\"\\nfor src in lines {\\n  let r = pcall(fn() { return calc(src, env) })\\n  if r[0] { print(format(\\\"%-26s => %s\\\", src, str(r[1]))) }\\n  else { print(format(\\\"%-26s !! %s\\\", src, str(r[1]))) }\\n}\\n\"},{\"name\":\"json.exb\",\"title\":\"مفسّر JSON\",\"code\":\"// json.exb — a JSON parser and pretty-printer written in EXBIN, using the\\n// regex-based lexer generator. Handles escapes, \\\\uXXXX, nesting, Arabic text.\\nlet lx = lexer([\\n  [\\\"_\\\", \\\"\\\\\\\\s+\\\"],\\n  [\\\"STR\\\", \\\"\\\\\\\"([^\\\\\\\"\\\\\\\\\\\\\\\\]|\\\\\\\\\\\\\\\\.)*\\\\\\\"\\\"],\\n  [\\\"NUM\\\", \\\"-?[0-9]+(\\\\\\\\.[0-9]+)?([eE][-+]?[0-9]+)?\\\"],\\n  [\\\"WORD\\\", \\\"[a-z]+\\\"],\\n  [\\\"{\\\", \\\"\\\\\\\\{\\\"], [\\\"}\\\", \\\"\\\\\\\\}\\\"], [\\\"[\\\", \\\"\\\\\\\\[\\\"], [\\\"]\\\", \\\"\\\\\\\\]\\\"], [\\\":\\\", \\\":\\\"], [\\\",\\\", \\\",\\\"]\\n])\\n\\nlet st = {toks: [], pos: 0}\\n\\nfn peek() { return st.toks[st.pos] }\\nfn advance() {\\n  let t = st.toks[st.pos]\\n  st.pos += 1\\n  return t\\n}\\nfn fail(msg) {\\n  let t = peek()\\n  error(format(\\\"JSON error at %d:%d: %s\\\", t.line, t.col, msg))\\n}\\nfn expect(type) {\\n  if peek().type != type { fail(\\\"expected '\\\" + type + \\\"' but found '\\\" + peek().text + \\\"'\\\") }\\n  return advance()\\n}\\n\\nfn unescape(raw) {\\n  let body = raw[range(1, raw.len - 1)]\\n  let out = \\\"\\\"\\n  let i = 0\\n  while i < body.len {\\n    let c = body[i]\\n    if c != \\\"\\\\\\\\\\\" {\\n      out += c\\n      i += 1\\n      continue\\n    }\\n    let e = body[i + 1]\\n    i += 2\\n    if e == \\\"n\\\" { out += \\\"\\\\n\\\" }\\n    else if e == \\\"t\\\" { out += \\\"\\\\t\\\" }\\n    else if e == \\\"r\\\" { out += \\\"\\\\r\\\" }\\n    else if e == \\\"b\\\" { out += \\\"\\\\b\\\" }\\n    else if e == \\\"f\\\" { out += \\\"\\\\f\\\" }\\n    else if e == \\\"u\\\" {\\n      out += chr(num(\\\"0x\\\" + body[range(i, i + 4)]))\\n      i += 4\\n    } else { out += e }\\n  }\\n  return out\\n}\\n\\nfn parse_value() {\\n  let t = advance()\\n  if t.type == \\\"STR\\\" { return unescape(t.text) }\\n  if t.type == \\\"NUM\\\" { return num(t.text) }\\n  if t.type == \\\"WORD\\\" {\\n    if t.text == \\\"true\\\" { return true }\\n    if t.text == \\\"false\\\" { return false }\\n    if t.text == \\\"null\\\" { return nil }\\n    st.pos -= 1\\n    fail(\\\"unknown word '\\\" + t.text + \\\"'\\\")\\n  }\\n  if t.type == \\\"[\\\" {\\n    let items = []\\n    if st.toks[st.pos].type == \\\"]\\\" {\\n      advance()\\n      return items\\n    }\\n    while true {\\n      items.push(parse_value())\\n      if peek().type == \\\",\\\" {\\n        advance()\\n        continue\\n      }\\n      expect(\\\"]\\\")\\n      return items\\n    }\\n  }\\n  if t.type == \\\"{\\\" {\\n    let obj = {}\\n    if peek().type == \\\"}\\\" {\\n      advance()\\n      return obj\\n    }\\n    while true {\\n      let key = unescape(expect(\\\"STR\\\").text)\\n      expect(\\\":\\\")\\n      obj[key] = parse_value()\\n      if peek().type == \\\",\\\" {\\n        advance()\\n        continue\\n      }\\n      expect(\\\"}\\\")\\n      return obj\\n    }\\n  }\\n  st.pos -= 1\\n  fail(\\\"unexpected '\\\" + t.text + \\\"'\\\")\\n}\\n\\nfn parse_json(src) {\\n  st.toks = lx.tokenize(src)\\n  st.pos = 0\\n  let v = parse_value()\\n  if peek().type != \\\"EOF\\\" { fail(\\\"trailing data\\\") }\\n  return v\\n}\\n\\nfn quote(s) {\\n  let out = \\\"\\\\\\\"\\\"\\n  for c in s {\\n    if c == \\\"\\\\\\\"\\\" { out += \\\"\\\\\\\\\\\\\\\"\\\" }\\n    else if c == \\\"\\\\\\\\\\\" { out += \\\"\\\\\\\\\\\\\\\\\\\" }\\n    else if c == \\\"\\\\n\\\" { out += \\\"\\\\\\\\n\\\" }\\n    else if c == \\\"\\\\t\\\" { out += \\\"\\\\\\\\t\\\" }\\n    else { out += c }\\n  }\\n  return out + \\\"\\\\\\\"\\\"\\n}\\n\\nfn stringify(v, indent, depth) {\\n  let t = type(v)\\n  if t == \\\"nil\\\" { return \\\"null\\\" }\\n  if t == \\\"string\\\" { return quote(v) }\\n  if t == \\\"number\\\" or t == \\\"bool\\\" { return str(v) }\\n  let pad = \\\"  \\\".repeat(depth + 1)\\n  let end = \\\"  \\\".repeat(depth)\\n  if t == \\\"list\\\" {\\n    if v.len == 0 { return \\\"[]\\\" }\\n    let parts = v.map(fn(x) { return pad + stringify(x, indent, depth + 1) })\\n    return \\\"[\\\\n\\\" + parts.join(\\\",\\\\n\\\") + \\\"\\\\n\\\" + end + \\\"]\\\"\\n  }\\n  if v.len == 0 { return \\\"{}\\\" }\\n  let parts = v.keys().map(fn(k) { return pad + quote(k) + \\\": \\\" + stringify(v[k], indent, depth + 1) })\\n  return \\\"{\\\\n\\\" + parts.join(\\\",\\\\n\\\") + \\\"\\\\n\\\" + end + \\\"}\\\"\\n}\\n\\nlet sample = \\\"{\\\\\\\"name\\\\\\\": \\\\\\\"EXBIN\\\\\\\", \\\\\\\"اسم\\\\\\\": \\\\\\\"لغة\\\\\\\", \\\\\\\"version\\\\\\\": 1.5e0,\\n  \\\\\\\"tags\\\\\\\": [\\\\\\\"vm\\\\\\\", \\\\\\\"tools\\\\\\\", true, null], \\\\\\\"nested\\\\\\\": {\\\\\\\"a\\\\\\\": [1, 2, {\\\\\\\"b\\\\\\\": \\\\\\\"x\\\\\\\\ny\\\\\\\"}], \\\\\\\"u\\\\\\\": \\\\\\\"\\\\\\\\u0639\\\\\\\"}}\\\"\\nlet doc = parse_json(sample)\\nprint(stringify(doc, 2, 0))\\nprint(\\\"keys:\\\", doc.keys())\\nprint(\\\"round-trip equal:\\\", parse_json(stringify(doc, 2, 0)) == doc)\\nlet bad = pcall(fn() { return parse_json(\\\"{\\\\\\\"a\\\\\\\": [1, 2,}\\\") })\\nprint(\\\"error case:\\\", bad[1])\\n\"},{\"name\":\"tinylang.exb\",\"title\":\"لغة صغيرة تُترجم إلى bytecode\",\"code\":\"// tinylang.exb — \\\"Tiny\\\": a small imperative language that COMPILES TO EXBIN\\n// BYTECODE with the asm toolkit, runs on the VM, and is saved as a .exbc file.\\n//\\n//   let n = 10          while cond { ... }        if cond { ... }\\n//   x = expr            print expr\\nlet pratt = require(\\\"pratt\\\")\\n\\nlet lx = lexer([\\n  [\\\"_\\\", \\\"\\\\\\\\s+\\\"], [\\\"_\\\", \\\"#[^\\\\\\\\n]*\\\"],\\n  [\\\"NUM\\\", \\\"[0-9]+(\\\\\\\\.[0-9]+)?\\\"],\\n  [\\\"STR\\\", \\\"\\\\\\\"[^\\\\\\\"]*\\\\\\\"\\\"],\\n  [\\\"IDENT\\\", \\\"[A-Za-z_\\\\\\\\x80-\\\\\\\\xff][A-Za-z0-9_\\\\\\\\x80-\\\\\\\\xff]*\\\"],\\n  [\\\"==\\\", \\\"==\\\"], [\\\"!=\\\", \\\"!=\\\"], [\\\"<=\\\", \\\"<=\\\"], [\\\">=\\\", \\\">=\\\"],\\n  [\\\"<\\\", \\\"<\\\"], [\\\">\\\", \\\">\\\"], [\\\"=\\\", \\\"=\\\"],\\n  [\\\"+\\\", \\\"\\\\\\\\+\\\"], [\\\"-\\\", \\\"-\\\"], [\\\"*\\\", \\\"\\\\\\\\*\\\"], [\\\"/\\\", \\\"/\\\"], [\\\"%\\\", \\\"%\\\"],\\n  [\\\"(\\\", \\\"\\\\\\\\(\\\"], [\\\")\\\", \\\"\\\\\\\\)\\\"], [\\\"{\\\", \\\"\\\\\\\\{\\\"], [\\\"}\\\", \\\"\\\\\\\\}\\\"]\\n], {keywords: {let: \\\"let\\\", print: \\\"print\\\", while: \\\"while\\\", if: \\\"if\\\"}})\\n\\n// ---- parser: expressions via Pratt, statements by recursive descent --------\\nlet spec = {prefix: {}, infix: {}}\\nspec.prefix[\\\"NUM\\\"] = fn(p, t) { return {type: \\\"num\\\", value: num(t.text)} }\\nspec.prefix[\\\"STR\\\"] = fn(p, t) { return {type: \\\"str\\\", value: t.text[range(1, t.text.len - 1)]} }\\nspec.prefix[\\\"IDENT\\\"] = fn(p, t) { return {type: \\\"var\\\", name: t.text} }\\nspec.prefix[\\\"(\\\"] = fn(p, t) {\\n  let e = p.parse(0)\\n  p.expect(\\\")\\\", nil)\\n  return e\\n}\\nspec.prefix[\\\"-\\\"] = pratt.unary(30)\\nfor op in [\\\"==\\\", \\\"!=\\\"] { spec.infix[op] = pratt.binary(5, false) }\\nfor op in [\\\"<\\\", \\\">\\\", \\\"<=\\\", \\\">=\\\"] { spec.infix[op] = pratt.binary(6, false) }\\nfor op in [\\\"+\\\", \\\"-\\\"] { spec.infix[op] = pratt.binary(10, false) }\\nfor op in [\\\"*\\\", \\\"/\\\", \\\"%\\\"] { spec.infix[op] = pratt.binary(20, false) }\\n\\nfn parse_block(p) {\\n  let stmts = []\\n  while not p.check(\\\"}\\\") and not p.at_end() { stmts.push(parse_stmt(p)) }\\n  p.expect(\\\"}\\\", nil)\\n  return stmts\\n}\\n\\nfn parse_stmt(p) {\\n  if p.match(\\\"let\\\") {\\n    let name = p.expect(\\\"IDENT\\\", \\\"expected a name\\\").text\\n    p.expect(\\\"=\\\", nil)\\n    return {type: \\\"let\\\", name: name, value: p.parse(0)}\\n  }\\n  if p.match(\\\"print\\\") { return {type: \\\"print\\\", value: p.parse(0)} }\\n  if p.match(\\\"while\\\") {\\n    let cond = p.parse(0)\\n    p.expect(\\\"{\\\", nil)\\n    return {type: \\\"while\\\", cond: cond, body: parse_block(p)}\\n  }\\n  if p.match(\\\"if\\\") {\\n    let cond = p.parse(0)\\n    p.expect(\\\"{\\\", nil)\\n    return {type: \\\"if\\\", cond: cond, body: parse_block(p)}\\n  }\\n  let name = p.expect(\\\"IDENT\\\", \\\"expected a statement\\\").text\\n  p.expect(\\\"=\\\", nil)\\n  return {type: \\\"set\\\", name: name, value: p.parse(0)}\\n}\\n\\nfn parse(src) {\\n  let p = pratt.parser(lx.tokenize(src), spec)\\n  let stmts = []\\n  while not p.at_end() { stmts.push(parse_stmt(p)) }\\n  return stmts\\n}\\n\\n// ---- code generator: AST -> EXBIN bytecode ----------------------------------\\nlet BINOPS = {\\\"+\\\": \\\"ADD\\\", \\\"-\\\": \\\"SUB\\\", \\\"*\\\": \\\"MUL\\\", \\\"/\\\": \\\"DIV\\\", \\\"%\\\": \\\"MOD\\\", \\\"<\\\": \\\"LESS\\\",\\n              \\\"<=\\\": \\\"LESS_EQUAL\\\", \\\">\\\": \\\"GREATER\\\", \\\">=\\\": \\\"GREATER_EQUAL\\\", \\\"==\\\": \\\"EQUAL\\\", \\\"!=\\\": \\\"NOT_EQUAL\\\"}\\nlet labels = {n: 0}\\nfn fresh(prefix) {\\n  labels.n += 1\\n  return prefix + str(labels.n)\\n}\\n\\nfn gen_expr(a, n) {\\n  let t = n.type\\n  if t == \\\"num\\\" or t == \\\"str\\\" { a.op(\\\"CONSTANT\\\", n.value) }\\n  else if t == \\\"var\\\" { a.op(\\\"GET_GLOBAL\\\", n.name) }\\n  else if t == \\\"neg\\\" or t == \\\"unary\\\" {\\n    gen_expr(a, n.operand)\\n    a.op(\\\"NEG\\\")\\n  } else {\\n    gen_expr(a, n.left)\\n    gen_expr(a, n.right)\\n    a.op(BINOPS[n.op])\\n  }\\n}\\n\\nfn gen_stmts(a, stmts) {\\n  for s in stmts { gen_stmt(a, s) }\\n}\\n\\nfn gen_stmt(a, s) {\\n  let t = s.type\\n  if t == \\\"let\\\" {\\n    gen_expr(a, s.value)\\n    a.op(\\\"DEFINE_GLOBAL\\\", s.name)\\n  } else if t == \\\"set\\\" {\\n    gen_expr(a, s.value)\\n    a.op(\\\"SET_GLOBAL\\\", s.name)\\n    a.op(\\\"POP\\\")\\n  } else if t == \\\"print\\\" {\\n    a.op(\\\"GET_GLOBAL\\\", \\\"print\\\")\\n    gen_expr(a, s.value)\\n    a.op(\\\"CALL\\\", 1)\\n    a.op(\\\"POP\\\")\\n  } else if t == \\\"while\\\" {\\n    let top = fresh(\\\"top\\\")\\n    let done = fresh(\\\"done\\\")\\n    a.label(top)\\n    gen_expr(a, s.cond)\\n    a.op(\\\"JUMP_IF_FALSE\\\", done)\\n    a.op(\\\"POP\\\")\\n    gen_stmts(a, s.body)\\n    a.op(\\\"LOOP\\\", top)\\n    a.label(done)\\n    a.op(\\\"POP\\\")\\n  } else if t == \\\"if\\\" {\\n    let other = fresh(\\\"else\\\")\\n    let end = fresh(\\\"end\\\")\\n    gen_expr(a, s.cond)\\n    a.op(\\\"JUMP_IF_FALSE\\\", other)\\n    a.op(\\\"POP\\\")\\n    gen_stmts(a, s.body)\\n    a.op(\\\"JUMP\\\", end)\\n    a.label(other)\\n    a.op(\\\"POP\\\")\\n    a.label(end)\\n  }\\n}\\n\\nfn compile_tiny(src) {\\n  let a = asm(\\\"<tiny>\\\", 0)\\n  gen_stmts(a, parse(src))\\n  a.op(\\\"NIL\\\").op(\\\"RETURN\\\")\\n  return a.build()\\n}\\n\\n// ---- demo --------------------------------------------------------------------\\nlet program = \\\"\\n# Fibonacci, then a little arithmetic\\nlet n = 10\\nlet a = 0\\nlet b = 1\\nwhile n > 0 {\\n  print a\\n  let t = a + b\\n  a = b\\n  b = t\\n  n = n - 1\\n}\\nif a > 50 { print \\\\\\\"a is big\\\\\\\" }\\nlet ناتج = (2 + 3) * 4 - 10 / 4\\nprint ناتج\\n\\\"\\n\\nlet main = compile_tiny(program)\\nprint(\\\"compiled:\\\", fn_info(main).code_size, \\\"bytes of bytecode\\\")\\nmain()\\n\\nsave_bytecode(main, \\\"/tmp/tiny.exbc\\\")\\nprint(\\\"--- reloaded from /tmp/tiny.exbc ---\\\")\\nload_bytecode(\\\"/tmp/tiny.exbc\\\")()\\n\"}]};\n\n/* EXBIN runtime worker: runs the WebAssembly VM off the UI thread so that\n   \"Stop\" can simply terminate it, and gives it a tiny in-memory file system\n   (so require(), read_file() and write_file() work). */\nif (typeof importScripts === 'function' && !self.EXB_DATA) importScripts('data.js');\n\nconst dec = new TextDecoder(), enc = new TextEncoder();\nlet modPromise = null;\nfunction getModule() {\n  if (!modPromise) {\n    // Standalone mode (opened from file://): the wasm is embedded as base64 by tools/build-inline.mjs.\n    modPromise = (self.EXB_WASM_B64\n      ? Promise.resolve(Uint8Array.from(atob(self.EXB_WASM_B64), (c) => c.charCodeAt(0)))\n      : fetch('exbin.wasm').then((r) => r.arrayBuffer())).then((b) => WebAssembly.compile(b));\n  }\n  return modPromise;\n}\n\nfunction normPath(p) {\n  const out = [];\n  for (const s of p.split('/')) {\n    if (!s || s === '.') continue;\n    if (s === '..') out.pop(); else out.push(s);\n  }\n  return '/' + out.join('/');\n}\n\nfunction makeRuntime(userFiles, stdinText) {\n  const stdin = enc.encode(stdinText || ''); let stdinPos = 0;\n  const fs = new Map(); // path -> {d: Uint8Array, n: length}\n  const put = (p, text) => { const d = enc.encode(text); fs.set(normPath(p), { d, n: d.length }); };\n  for (const [k, v] of Object.entries(self.EXB_DATA.lib)) put('/lib/' + k, v);\n  for (const [k, v] of Object.entries(userFiles || {})) put('/' + k, v);\n\n  const open = new Map(); // fd -> {f, pos, w, append}\n  let nextFd = 10;\n  let mem = null;\n  const view = () => new DataView(mem.buffer);\n  const u8 = () => new Uint8Array(mem.buffer);\n\n  const E_BADF = 8, E_NOENT = 44, E_SPIPE = 70, E_INVAL = 28;\n  const wasi = {\n    environ_sizes_get: (c, s) => { view().setUint32(c, 0, true); view().setUint32(s, 0, true); return 0; },\n    environ_get: () => 0,\n    clock_time_get: (id, prec, out) => {\n      const ms = id === 0 ? Date.now() : performance.now();\n      view().setBigUint64(out, BigInt(Math.round(ms * 1e6)), true);\n      return 0;\n    },\n    fd_close: (fd) => { open.delete(fd); return 0; },\n    fd_fdstat_get: (fd, p) => {\n      const v = view();\n      v.setUint8(p, fd < 3 ? 2 : (fd === 3 ? 3 : 4));\n      v.setUint16(p + 2, 0, true);\n      v.setBigUint64(p + 8, 0xffffffffffffffffn, true);\n      v.setBigUint64(p + 16, 0xffffffffffffffffn, true);\n      return 0;\n    },\n    fd_fdstat_set_flags: () => 0,\n    fd_prestat_get: (fd, p) => {\n      if (fd !== 3) return E_BADF;\n      view().setUint8(p, 0); view().setUint32(p + 4, 1, true); return 0;\n    },\n    fd_prestat_dir_name: (fd, p, len) => { if (fd !== 3) return E_BADF; u8()[p] = 47; return 0; },\n    fd_read: (fd, iovs, n, outp) => {\n      const v = view(); let total = 0;\n      const o = open.get(fd);\n      if (o) {\n        for (let i = 0; i < n; i++) {\n          const buf = v.getUint32(iovs + i * 8, true), len = v.getUint32(iovs + i * 8 + 4, true);\n          const c = Math.max(0, Math.min(len, o.f.n - o.pos));\n          u8().set(o.f.d.subarray(o.pos, o.pos + c), buf);\n          o.pos += c; total += c;\n          if (c < len) break;\n        }\n      } else if (fd === 0) {\n        for (let i = 0; i < n; i++) {\n          const buf = v.getUint32(iovs + i * 8, true), len = v.getUint32(iovs + i * 8 + 4, true);\n          const c = Math.max(0, Math.min(len, stdin.length - stdinPos));\n          u8().set(stdin.subarray(stdinPos, stdinPos + c), buf);\n          stdinPos += c; total += c;\n          if (c < len) break;\n        }\n      } else return E_BADF;\n      v.setUint32(outp, total, true); return 0;\n    },\n    fd_seek: (fd, off, whence, outp) => {\n      const o = open.get(fd); if (!o) return E_SPIPE;\n      off = Number(off);\n      const np = whence === 0 ? off : whence === 1 ? o.pos + off : o.f.n + off;\n      if (np < 0) return E_INVAL;\n      o.pos = np; view().setBigUint64(outp, BigInt(np), true); return 0;\n    },\n    fd_write: (fd, iovs, n, outp) => {\n      const v = view(); let total = 0;\n      const o = open.get(fd);\n      for (let i = 0; i < n; i++) {\n        const buf = v.getUint32(iovs + i * 8, true), len = v.getUint32(iovs + i * 8 + 4, true);\n        if (o) {\n          if (!o.w) return E_BADF;\n          if (o.append) o.pos = o.f.n;\n          const need = o.pos + len;\n          if (need > o.f.d.length) { const nd = new Uint8Array(Math.max(need, o.f.d.length * 2, 64)); nd.set(o.f.d.subarray(0, o.f.n)); o.f.d = nd; }\n          o.f.d.set(u8().subarray(buf, buf + len), o.pos);\n          o.pos += len; if (o.pos > o.f.n) o.f.n = o.pos;\n        } else if (fd === 1 || fd === 2) {\n          extra.push(dec.decode(u8().subarray(buf, buf + len)));\n        } else return E_BADF;\n        total += len;\n      }\n      v.setUint32(outp, total, true); return 0;\n    },\n    path_open: (dirfd, dflags, pp, pl, oflags, rb, ri, fdflags, outp) => {\n      if (dirfd !== 3) return E_BADF;\n      const p = normPath(dec.decode(u8().subarray(pp, pp + pl)));\n      let f = fs.get(p);\n      const write = (BigInt(rb) & 64n) !== 0n || (oflags & 9) !== 0;\n      if (!f) {\n        if (!(oflags & 1)) return E_NOENT;\n        f = { d: new Uint8Array(64), n: 0 }; fs.set(p, f);\n      } else if (oflags & 8) f.n = 0;\n      const fd = nextFd++;\n      open.set(fd, { f, pos: 0, w: write, append: (fdflags & 1) !== 0 });\n      view().setUint32(outp, fd, true); return 0;\n    },\n    proc_exit: (code) => { const e = new Error('exit'); e.exitCode = code; throw e; },\n  };\n  const extra = [];\n  return { wasi, extra, setMem: (m) => { mem = m; } };\n}\n\nasync function run(msg) {\n  const t0 = performance.now();\n  const mod = await getModule();\n  const rt = makeRuntime(msg.files, msg.stdin);\n  const inst = await WebAssembly.instantiate(mod, { wasi_snapshot_preview1: rt.wasi });\n  const x = inst.exports;\n  rt.setMem(x.memory);\n  const bytes = enc.encode(msg.src);\n  const ptr = x.exb_alloc(bytes.length + 1);\n  new Uint8Array(x.memory.buffer).set(bytes, ptr);\n  new Uint8Array(x.memory.buffer)[ptr + bytes.length] = 0;\n  let status = 0, exit = null;\n  try {\n    status = (msg.cmd === 'disasm' || msg.cmd === 'check') ? x.exb_disasm(ptr) : x.exb_run(ptr);\n  } catch (e) {\n    if (e && e.exitCode !== undefined) exit = e.exitCode; else throw e;\n  }\n  const out = dec.decode(new Uint8Array(x.memory.buffer, x.exb_out(), x.exb_len())) + rt.extra.join('');\n  return { status, out, exit, ms: performance.now() - t0, version: dec.decode(new Uint8Array(x.memory.buffer, x.exb_version(), 16)).split('\\0')[0] };\n}\n\nself.onmessage = async (e) => {\n  const m = e.data;\n  try {\n    if (m.cmd === 'init') {\n      await getModule();\n      self.postMessage({ id: m.id, ready: true });\n      return;\n    }\n    const r = await run(m);\n    self.postMessage({ id: m.id, cmd: m.cmd, ...r });\n  } catch (err) {\n    self.postMessage({ id: m.id, status: 3, out: 'Internal error: ' + (err && err.message || err), ms: 0 });\n  }\n};\n"};
